<template><view v-if="activity" class="page room-page"><view class="tabs"><button v-for="(t,i) in tabs" :key="t" :class="{active:tab===i}" @click="tab=i"><text>{{ t }}</text></button></view><ChatTab v-if="tab===0" :activity-id="id" :refresh-key="refreshKey" /><SignTab v-if="tab===1" :activity-id="id" :creator="activity.creator" :refresh-key="refreshKey" /><AlbumTab v-if="tab===2" :activity-id="id" :refresh-key="refreshKey" /><LocationTab v-if="tab===3" :activity-id="id" :refresh-key="refreshKey" /></view></template>
<script setup lang="ts">import{ref}from'vue';import{onLoad,onUnload,onShow}from'@dcloudio/uni-app';import{api}from'@/services/api';import{ActivitySocket}from'@/services/realtime';import type{Activity}from'@/services/types';import ChatTab from'@/components/room/ChatTab.vue';import SignTab from'@/components/room/SignTab.vue';import AlbumTab from'@/components/room/AlbumTab.vue';import LocationTab from'@/components/room/LocationTab.vue';const id=ref(0),activity=ref<Activity|null>(null),tab=ref(0),tabs=['聊天','签到','相册','位置'],refreshKey=ref(0);let socket:ActivitySocket|null=null;onLoad(async(o:any)=>{id.value=Number(o.id);const loaded=await api<Activity>(`/activities/${id.value}`);activity.value=loaded;if(!loaded.joined){uni.showToast({title:'请先报名活动',icon:'none'});return uni.navigateBack()}socket=new ActivitySocket(id.value);socket.on(()=>refreshKey.value++);await socket.connect()});onShow(()=>refreshKey.value++);onUnload(()=>socket?.close())</script>
<style scoped lang="scss">
.room-page{padding-top:20rpx}.tabs{position:sticky;top:0;z-index:5;display:flex;width:100%;margin-bottom:28rpx;padding:7rpx;background:#e4ecea;border-radius:20rpx;gap:4rpx}.tabs button{display:flex;align-items:center;justify-content:center;flex:1;min-width:0;height:72rpx;margin:0;padding:0 8rpx;color:$text-muted;font-size:25rpx;font-weight:650;line-height:1;white-space:nowrap;background:transparent;border-radius:15rpx}.tabs .active{color:#fff;background:$primary;box-shadow:0 6rpx 16rpx rgba(15,118,110,.18)}
</style>
